package cipipeline

import (
	_ "embed"
	"strings"
)

// installerSource is a copy of the repository's install.sh (the file users
// curl for a first install). The two must stay identical: a test fails when
// they differ, and the fix is `cp install.sh apps/smith/cipipeline/smith_installer.sh`.
// The script verifies the downloaded binary against the release's checksums.txt.
//
//go:embed smith_installer.sh
var installerSource string

const installerHeader = "# Generated by smith (`smith ci generate`) from the installer shipped with this smith.\n" +
	"# Do not edit: `smith ci generate` and `smith doctor --fix` rewrite this file.\n"

// InstallScript is the installer written to InstallScriptPath: the embedded
// install.sh with a generated-file header after its shebang line.
func InstallScript() string {
	src := strings.ReplaceAll(installerSource, "\r\n", "\n")
	first, rest, found := strings.Cut(src, "\n")
	if !found {
		return installerHeader + src
	}
	return first + "\n" + installerHeader + rest
}
